#!/usr/bin/env node
/**
 * patch-cooper-hewitt.mjs
 * Run from the project root:  node patch-cooper-hewitt.mjs
 * Undo:                       node patch-cooper-hewitt.mjs --restore
 *
 * - Replaces Plus Jakarta Sans + DM Sans with Cooper Hewitt (self-hosted via next/font/local)
 * - Retunes letter-spacing for the wider letterforms
 * - Makes these ALL CAPS: "Hi, I'm Carlo.", "Selected projects", "What I build with.",
 *   Tech Stack category titles, "Got a project in mind? Let's Talk!", "Free consultation / No commitment"
 *
 * Idempotent: running it twice changes nothing the second time. Every anchor is checked
 * before anything is written, so a mismatch aborts with no partial edits.
 */
import fs from "node:fs";
import path from "node:path";

// ── Options ────────────────────────────────────────────────────────────────
// The big hero ("Building Systems That Make Ideas Work.") is left as-is.
// Set true to uppercase it too.
const UPPERCASE_BUILDING_HERO = false;

// ── Embedded assets (Cooper Hewitt, SIL Open Font License 1.1) ─────────────
const FONTS = {
  "CooperHewitt-Book.woff2": "",
  "CooperHewitt-Medium.woff2": "",
  "CooperHewitt-Semibold.woff2": "",
  "CooperHewitt-Bold.woff2": "",
  "CooperHewitt-Heavy.woff2": ""
};
const OFL_B64 = "";

// ── Plumbing ───────────────────────────────────────────────────────────────
const ROOT = process.cwd();
const MARK = "cooper-hewitt:applied";
const BACKUP_DIR = path.join(ROOT, ".patch-backups", "cooper-hewitt");
const P = (...a) => path.join(ROOT, ...a);
const FILES = ["app/layout.js", "app/globals.css", "app/page.js", "app/ContactMorphSection.js", "tailwind.config.js"];
const bakName = (f) => path.join(BACKUP_DIR, f.replace(/[\\/]/g, "__") + ".bak");

function fail(msg) {
  console.error("\n✖ " + msg + "\nNothing was written.");
  process.exit(1);
}

if (!fs.existsSync(P("app", "layout.js")) || !fs.existsSync(P("app", "globals.css"))) {
  fail("Run this from the project root (the folder that contains app/ and package.json).");
}

// ── Restore mode ───────────────────────────────────────────────────────────
if (process.argv.includes("--restore")) {
  let n = 0;
  for (const f of FILES) {
    const b = bakName(f);
    if (fs.existsSync(b)) {
      fs.copyFileSync(b, P(f));
      n++;
      console.log("↩ restored " + f);
    }
  }
  fs.rmSync(P("app", "fonts"), { recursive: true, force: true });
  console.log(n ? "\nRestored " + n + " file(s) and removed app/fonts." : "No backups found, nothing to restore.");
  process.exit(0);
}

const countOf = (src, s) => src.split(s).length - 1;
function replaceOnce(src, from, to, label) {
  const c = countOf(src, from);
  if (c !== 1) fail(`Anchor "${label}" matched ${c} time(s), expected 1.`);
  return src.replace(from, () => to);
}
function setRuleTracking(css, selector, value) {
  const esc = selector.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp("(^|\\n)(" + esc + "\\s*\\{[^}]*?letter-spacing:\\s*)[^;]+;");
  if (!re.test(css)) fail(`CSS rule "${selector}" with letter-spacing not found.`);
  return css.replace(re, (_, a, b) => a + b + value + ";");
}

// ── Per-file edits ─────────────────────────────────────────────────────────
function patchLayout(src) {
  src = replaceOnce(
    src,
    'import { Plus_Jakarta_Sans, DM_Sans } from "next/font/google";',
    'import localFont from "next/font/local";',
    "layout: font import"
  );
  const re =
    /\/\/ Display \/ headings\s*const plusJakarta = Plus_Jakarta_Sans\(\{[\s\S]*?\}\);\s*\/\/ Body \/ labels\s*const dmSans = DM_Sans\(\{[\s\S]*?\}\);/;
  if (!re.test(src)) fail('Anchor "layout: font definitions" not found.');
  const block = `// Cooper Hewitt (SIL OFL): one family drives both --font-display and --font-body
const cooper = localFont({
  src: [
    { path: "./fonts/CooperHewitt-Book.woff2", weight: "400", style: "normal" },
    { path: "./fonts/CooperHewitt-Medium.woff2", weight: "500", style: "normal" },
    { path: "./fonts/CooperHewitt-Semibold.woff2", weight: "600", style: "normal" },
    { path: "./fonts/CooperHewitt-Bold.woff2", weight: "700", style: "normal" },
    { path: "./fonts/CooperHewitt-Heavy.woff2", weight: "800", style: "normal" },
  ],
  variable: "--font-cooper",
  display: "swap",
});`;
  src = src.replace(re, () => block);
  src = replaceOnce(
    src,
    "className={`${plusJakarta.variable} ${dmSans.variable}`}",
    "className={cooper.variable}",
    "layout: html className"
  );
  return src + `\n// ${MARK}\n`;
}

function patchGlobals(src) {
  src = replaceOnce(
    src,
    "--font-display: var(--font-jakarta), 'Plus Jakarta Sans', system-ui, sans-serif;",
    "--font-display: var(--font-cooper), 'Cooper Hewitt', system-ui, sans-serif;",
    "globals: --font-display"
  );
  src = replaceOnce(
    src,
    "--font-body:    var(--font-dmsans), 'DM Sans', system-ui, sans-serif;",
    "--font-body:    var(--font-cooper), 'Cooper Hewitt', system-ui, sans-serif;",
    "globals: --font-body"
  );
  // Cooper Hewitt is wider than Jakarta, so the very tight tracking is loosened
  src = setRuleTracking(src, ".tsd-title", "-0.03em");
  src = setRuleTracking(src, ".tsd-card-title", "0.01em");
  src = setRuleTracking(src, ".ip-title", "-0.02em");
  src = setRuleTracking(src, ".svc-heading", "-0.03em");
  src = setRuleTracking(src, ".svc-title", "-0.02em");
  src += `
/* cooper-hewitt:start */
/* ALL CAPS: intro title ("Hi, I'm Carlo."), Tech Stack heading and category titles */
.ip-title,
.tsd-title,
.tsd-card-title { text-transform: uppercase; }
/* cooper-hewitt:end */
/* ${MARK} */
`;
  return src;
}

function patchPage(src) {
  // "Selected projects" -> all caps
  src = replaceOnce(
    src,
    "font-display font-extrabold tracking-[-0.045em] leading-[1.1]",
    "font-display font-extrabold uppercase tracking-[-0.025em] leading-[1.1]",
    'page: "Selected projects" heading'
  );
  // Building Systems hero (tracking, optional caps)
  src = replaceOnce(
    src,
    "font-extrabold leading-none tracking-[-0.055em] text-center",
    "font-extrabold leading-none " + (UPPERCASE_BUILDING_HERO ? "uppercase " : "") + "tracking-[-0.03em] text-center",
    "page: hero heading"
  );
  // Remaining display text tracking
  src = replaceOnce(src, "leading-[1.05] tracking-[-0.045em] mt-2", "leading-[1.05] tracking-[-0.025em] mt-2", "page: project card title");
  src = replaceOnce(src, 'letterSpacing: "-0.045em",', 'letterSpacing: "-0.025em",', "page: manifesto lines");
  src = replaceOnce(src, "font-semibold leading-[1.3] tracking-[-0.035em]", "font-semibold leading-[1.3] tracking-[-0.02em]", "page: story text");
  src = replaceOnce(src, "font-medium leading-[1.5] tracking-[-0.03em]", "font-medium leading-[1.5] tracking-[-0.015em]", "page: testimonial text");
  return src + `\n/* ${MARK} */\n`;
}

function patchContact(src) {
  src = replaceOnce(
    src,
    "&family=DM+Sans:wght@400..600&family=Plus+Jakarta+Sans:wght@500..800",
    "",
    "contact: remove Google DM Sans / Jakarta"
  );
  src = replaceOnce(
    src,
    "font-family:'Plus Jakarta Sans','Noto Sans',system-ui,sans-serif;-webkit-font-smoothing",
    "font-family:var(--font-display),'Noto Sans',system-ui,sans-serif;-webkit-font-smoothing",
    "contact: root font"
  );
  src = replaceOnce(
    src,
    "font-family:'DM Sans',system-ui,sans-serif;font-weight:400",
    "font-family:var(--font-body),system-ui,sans-serif;font-weight:400",
    "contact: ct-top font"
  );
  src = replaceOnce(
    src,
    `var SANS = "'Plus Jakarta Sans','Noto Sans',system-ui,sans-serif";`,
    `var SANS = "var(--font-display),'Noto Sans',system-ui,sans-serif";`,
    "contact: morph SANS stack"
  );
  src = replaceOnce(src, 'var LAT = { font: SANS, ls: "-0.055em", fs: 1 };', 'var LAT = { font: SANS, ls: "-0.03em", fs: 1 };', "contact: morph tracking");
  src = replaceOnce(src, "letter-spacing:-.055em;line-height:1.15;padding:.1em .06em", "letter-spacing:-.03em;line-height:1.15;padding:.1em .06em", "contact: ct-morph tracking");
  src = replaceOnce(src, "line-height:1.08;letter-spacing:-.04em", "line-height:1.08;letter-spacing:-.02em", "contact: ct-lead tracking");
  // all caps + room for two lines on desktop
  const re = /("\/\* \/ct-one-line \*\/")\s*\]\.join/;
  if (!re.test(src)) fail('Anchor "contact: CSS array end" not found.');
  src = src.replace(
    re,
    (_, last) =>
      last +
      `,
  "/* cooper-hewitt */",
  ".ct-root .ct-lead,.ct-root .ct-top{text-transform:uppercase}",
  ".ct-root .ct-top{letter-spacing:.02em}",
  "@media (min-width:768px){.ct-root .ct-lead{max-width:18em}}"
].join`
  );
  return src + `\n/* ${MARK} */\n`;
}

function patchTailwind(src) {
  return src
    .replace("// Plus Jakarta Sans (headings)", "// Cooper Hewitt (headings)")
    .replace("// DM Sans (body)", "// Cooper Hewitt (body)");
}

const PATCHERS = {
  "app/layout.js": patchLayout,
  "app/globals.css": patchGlobals,
  "app/page.js": patchPage,
  "app/ContactMorphSection.js": patchContact,
  "tailwind.config.js": patchTailwind,
};

// ── Plan every edit in memory first ────────────────────────────────────────
const pending = [];
const skipped = [];
for (const f of FILES) {
  if (!fs.existsSync(P(f))) {
    if (f === "tailwind.config.js") continue;
    fail(`Missing file: ${f}`);
  }
  const src = fs.readFileSync(P(f), "utf8");
  if (src.includes(MARK) || (f === "tailwind.config.js" && !src.includes("Plus Jakarta Sans (headings)") && !src.includes("DM Sans (body)"))) {
    skipped.push(f);
    continue;
  }
  pending.push([f, PATCHERS[f](src)]);
}

// ── Write ──────────────────────────────────────────────────────────────────
fs.mkdirSync(BACKUP_DIR, { recursive: true });
for (const [f, out] of pending) {
  const b = bakName(f);
  if (!fs.existsSync(b)) fs.copyFileSync(P(f), b);
  fs.writeFileSync(P(f), out);
  console.log("✔ patched " + f);
}
for (const f of skipped) console.log("• already patched " + f);

fs.mkdirSync(P("app", "fonts"), { recursive: true });
for (const [name, b64] of Object.entries(FONTS)) {
  fs.writeFileSync(P("app", "fonts", name), Buffer.from(b64, "base64"));
}
fs.writeFileSync(P("app", "fonts", "OFL.txt"), Buffer.from(OFL_B64, "base64"));
console.log("✔ wrote app/fonts (" + Object.keys(FONTS).length + " WOFF2 files + OFL.txt)");

console.log(`
Done. Backups: .patch-backups/cooper-hewitt/   Undo: node patch-cooper-hewitt.mjs --restore
Restart "npm run dev" so Next picks up the new fonts.`);
